const fold=v=>String(v||'').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().replace(/\s+/g,' ').trim();
export function europeCityPrefixMatches(prefix,countryNames=[]){
 const p=fold(prefix),countries=new Set(countryNames.map(fold).filter(Boolean));
 if(!p||!countries.size)return [];
 return ROWS.filter(([name,country])=>countries.has(fold(country))&&fold(name).startsWith(p))
  .map(([name,country,region])=>({name,country,region,source:'GeoNames CC BY 4.0'}));
}
